import { initializeApp, getApps, FirebaseApp } from 'firebase/app';
import { getAuth, Auth } from 'firebase/auth';
import { getFirestore, Firestore, doc, getDocFromServer } from 'firebase/firestore';

// 1. Check AI Studio Preview configuration from firebase-applet-config.json (generated by AI Studio Firebase tool)
const appletConfigs = import.meta.glob<Record<string, any>>(
  ['/firebase-applet-config.json', '/firebase_applet_config.json'],
  { eager: true }
);

const appletConfig =
  appletConfigs['/firebase-applet-config.json']?.default ||
  appletConfigs['/firebase-applet-config.json'] ||
  appletConfigs['/firebase_applet_config.json']?.default ||
  appletConfigs['/firebase_applet_config.json'] ||
  {};

// 2. Read environment variables (used in Netlify production or overridden by .env)
const envApiKey = (import.meta.env.VITE_FIREBASE_API_KEY || '').trim();
const envProjectId = (import.meta.env.VITE_FIREBASE_PROJECT_ID || '').trim();
const envAuthDomain = (import.meta.env.VITE_FIREBASE_AUTH_DOMAIN || '').trim();
const envStorageBucket = (import.meta.env.VITE_FIREBASE_STORAGE_BUCKET || '').trim();
const envMessagingSenderId = (import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID || '').trim();
const envAppId = (import.meta.env.VITE_FIREBASE_APP_ID || '').trim();

const hasEnvConfig = Boolean(
  envApiKey &&
  envProjectId &&
  envApiKey.length > 20 &&
  !envApiKey.includes('your-api-key') &&
  !envApiKey.includes('MY_FIREBASE_API_KEY') &&
  !envApiKey.includes('0000000000')
);

const hasAppletConfig = Boolean(
  appletConfig.apiKey &&
  appletConfig.projectId &&
  typeof appletConfig.apiKey === 'string' &&
  appletConfig.apiKey.length > 20 &&
  appletConfig.projectId !== 'remixed-project-id'
);

export type FirebaseConfigSource = 'env' | 'applet_config' | 'none';
export const configSource: FirebaseConfigSource = hasEnvConfig
  ? 'env'
  : hasAppletConfig
  ? 'applet_config'
  : 'none';

export const isFirebaseConfigured: boolean = hasEnvConfig || hasAppletConfig;

const rawApiKey = (hasEnvConfig ? envApiKey : appletConfig.apiKey || '').trim();
const rawProjectId = (hasEnvConfig ? envProjectId : appletConfig.projectId || '').trim();
const rawAuthDomain = (
  hasEnvConfig ? envAuthDomain : appletConfig.authDomain || (rawProjectId ? `${rawProjectId}.firebaseapp.com` : '')
).trim();
const rawStorageBucket = (
  hasEnvConfig ? envStorageBucket : appletConfig.storageBucket || (rawProjectId ? `${rawProjectId}.firebasestorage.app` : '')
).trim();
const rawMessagingSenderId = (
  hasEnvConfig ? envMessagingSenderId : appletConfig.messagingSenderId || ''
).trim();
const rawAppId = (hasEnvConfig ? envAppId : appletConfig.appId || '').trim();
const rawDatabaseId: string | undefined =
  hasAppletConfig &&
  appletConfig.firestoreDatabaseId &&
  (!hasEnvConfig || !envProjectId || envProjectId === appletConfig.projectId)
    ? String(appletConfig.firestoreDatabaseId).trim()
    : (import.meta.env.VITE_FIREBASE_FIRESTORE_DATABASE_ID || '').trim() || undefined;

export const firebaseProjectHost: string = (() => {
  if (!isFirebaseConfigured || !rawProjectId) return 'Not Configured';
  return `${rawProjectId}.firebaseapp.com`;
})();

let appInstance: FirebaseApp;
let authInstance: Auth;
let dbInstance: Firestore;

if (isFirebaseConfigured) {
  const firebaseConfig = {
    apiKey: rawApiKey,
    authDomain: rawAuthDomain || `${rawProjectId}.firebaseapp.com`,
    projectId: rawProjectId,
    storageBucket: rawStorageBucket || `${rawProjectId}.firebasestorage.app`,
    messagingSenderId: rawMessagingSenderId || undefined,
    appId: rawAppId || undefined
  };

  appInstance = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];
  authInstance = getAuth(appInstance);
  dbInstance = rawDatabaseId ? getFirestore(appInstance, rawDatabaseId) : getFirestore(appInstance);
} else {
  // Safe unconfigured stubs that clearly signal unconfigured state instead of using fake credentials
  appInstance = (getApps().length > 0 ? getApps()[0] : { name: '[UNCONFIGURED]' }) as FirebaseApp;
  
  const createUnconfiguredProxy = (serviceName: string) =>
    new Proxy({} as any, {
      get(_target, prop) {
        if (prop === 'currentUser') return null;
        if (prop === 'onAuthStateChanged') {
          return (cb: (u: null) => void) => {
            cb(null);
            return () => {};
          };
        }
        return () => {
          throw new Error(
            `Cannot use Firebase ${serviceName}: Firebase is not configured. For Google AI Studio Preview, confirm the Firebase prompt; for Netlify production, configure VITE_FIREBASE_* environment variables.`
          );
        };
      }
    });

  authInstance = createUnconfiguredProxy('Auth');
  dbInstance = createUnconfiguredProxy('Firestore');
}

export const app: FirebaseApp = appInstance;
export const auth: Auth = authInstance;
export const db: Firestore = dbInstance;

export async function testFirebaseConnection(): Promise<{ reachable: boolean; error?: string }> {
  if (!isFirebaseConfigured) {
    return {
      reachable: false,
      error: 'Firebase is not configured. Set up Firebase in AI Studio Preview or configure VITE_FIREBASE_* variables in Netlify.'
    };
  }

  try {
    // Perform a genuine server-side roundtrip connection test to Firestore
    await getDocFromServer(doc(db, '_health_check', 'ping')).catch((err) => {
      // Permission-denied or not-found confirms server was reached and evaluated rules
      if (err?.code === 'permission-denied' || err?.code === 'not-found') {
        return;
      }
      throw err;
    });
    return { reachable: true };
  } catch (err) {
    return {
      reachable: false,
      error: err instanceof Error ? err.message : 'Unable to connect to Firebase backend.'
    };
  }
}

export function getFirebaseConfigSummary() {
  const mask = (str: string) => {
    if (!str) return 'Not set';
    if (str.length <= 8) return '****';
    return `${str.slice(0, 4)}...${str.slice(-4)}`;
  };

  return {
    isConfigured: isFirebaseConfigured,
    source: configSource,
    sourceLabel:
      configSource === 'applet_config'
        ? 'AI Studio Preview Config (firebase-applet-config.json)'
        : configSource === 'env'
        ? 'Production Environment Variables (VITE_FIREBASE_*)'
        : 'Not Configured',
    projectId: rawProjectId || 'Not set',
    databaseId: rawDatabaseId || '(default)',
    authDomain: rawAuthDomain || (rawProjectId ? `${rawProjectId}.firebaseapp.com` : 'Not set'),
    storageBucket: rawStorageBucket || (rawProjectId ? `${rawProjectId}.firebasestorage.app` : 'Not set'),
    hasApiKey: Boolean(rawApiKey && rawApiKey.length > 20),
    apiKeyMasked: mask(rawApiKey),
    messagingSenderIdMasked: mask(rawMessagingSenderId),
    appIdMasked: mask(rawAppId)
  };
}
